document.addEventListener("DOMContentLoaded", () => {
        const cuerpo = document.body;
            const botonModo = document.getElementById("modo");
                const tarjetas = document.querySelectorAll(
                        "#zumos .producto, #licuados .producto"
                            );

                                let temporizadorAviso;

                                    // 1. NOTIFICACIONES
                                        function mostrarNotificacion(mensaje) {
                                                let aviso = document.getElementById("notificacion-jugos");

                                                        if (!aviso) {
                                                                    aviso = document.createElement("div");
                                                                                aviso.id = "notificacion-jugos";
                                                                                            aviso.className = "notificacion-js";
                                                                                                        aviso.setAttribute("role", "status");
                                                                                                                    aviso.setAttribute("aria-live", "polite");
                                                                                                                                cuerpo.appendChild(aviso);
                                                                                                                                        }

                                                                                                                                                aviso.textContent = mensaje;
                                                                                                                                                        aviso.hidden = false;

                                                                                                                                                                clearTimeout(temporizadorAviso);

                                                                                                                                                                        temporizadorAviso = setTimeout(() => {
                                                                                                                                                                                    aviso.hidden = true;
                                                                                                                                                                                            }, 3200);
                                                                                                                                                                                                }

                                                                                                                                                                                                    // 2. BOTÓN VER RECETAS
                                                                                                                                                                                                        window.mostrarMensaje = function () {
                                                                                                                                                                                                                mostrarNotificacion(
                                                                                                                                                                                                                            "🥤 ¡Excelente decisión! Descubre nuestras recetas naturales."
                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                            // 3. MODO OSCURO Y MODO CLARO
                                                                                                                                                                                                                                                function actualizarModo() {
                                                                                                                                                                                                                                                        if (!botonModo) return;

                                                                                                                                                                                                                                                                const oscuro = cuerpo.classList.contains("oscuro");

                                                                                                                                                                                                                                                                        botonModo.textContent = oscuro ? "☀️" : "🌙";
                                                                                                                                                                                                                                                                                botonModo.setAttribute(
                                                                                                                                                                                                                                                                                            "aria-label",
                                                                                                                                                                                                                                                                                                        oscuro ? "Activar modo claro" : "Activar modo oscuro"
                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                        botonModo.setAttribute("aria-pressed", String(oscuro));
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                if (botonModo) {
                                                                                                                                                                                                                                                                                                                                        botonModo.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                    cuerpo.classList.toggle("oscuro");
                                                                                                                                                                                                                                                                                                                                                                actualizarModo();

                                                                                                                                                                                                                                                                                                                                                                            mostrarNotificacion(
                                                                                                                                                                                                                                                                                                                                                                                            cuerpo.classList.contains("oscuro")
                                                                                                                                                                                                                                                                                                                                                                                                                ? "🌙 Modo oscuro activado."
                                                                                                                                                                                                                                                                                                                                                                                                                                    : "☀️ Modo claro activado."
                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                actualizarModo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 4. NAVEGACIÓN SUAVE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll('a[href^="#"]').forEach(enlace => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    enlace.addEventListener("click", evento => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const destino = enlace.getAttribute("href");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!destino || destino === "#") return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const seccion = document.querySelector(destino);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!seccion) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            seccion.scrollIntoView({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            behavior: "smooth",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            block: "start"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    history.replaceState(null, "", destino);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 5. INTERACCIÓN CON LAS TARJETAS DE ZUMOS Y LICUADOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarjetas.forEach(tarjeta => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const titulo = tarjeta.querySelector("h3");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!titulo) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarjeta.addEventListener("click", evento => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            evento.target.closest(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "a, button, input, select, textarea"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarNotificacion(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "🥤 " + titulo.textContent.trim() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ": revisa sus ingredientes y preparación."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 6. DETECTAR IMÁGENES QUE NO CARGAN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll("img").forEach(imagen => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                imagen.addEventListener("error", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            imagen.classList.add("imagen-error");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const texto = imagen.getAttribute("alt") || "Imagen";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!texto.includes("(no disponible)")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    imagen.setAttribute(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "alt",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            texto + " (no disponible)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, { once: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 7. CARGA DIFERIDA DE VIDEOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll("#videos iframe").forEach(video => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    video.setAttribute("loading", "lazy");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            video.setAttribute(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "referrerpolicy",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "strict-origin-when-cross-origin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 8. AÑO AUTOMÁTICO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const anio = document.getElementById("anio-actual");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (anio) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    anio.textContent = new Date().getFullYear();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 9. COMPROBACIÓN EN LA CONSOLA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.info("Jugos Naturales: JavaScript cargado correctamente.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.info("Tarjetas de recetas detectadas:", tarjetas.length);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

